const FEED='https://res.stj.jus.br/hrestp-c-portalp/RSS.xml';
function clean(s){return s.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]*>/g,'').replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(Number(n))).replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim()}
function parseFeed(xml){return [...xml.matchAll(/<item(?:\s[^>]*)?>([\s\S]*?)<\/item>/gi)].map(([,s])=>{const field=n=>clean(s.match(new RegExp('<'+n+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+n+'>','i'))?.[1]||'');const title=field('title'),link=field('link'),date=field('pubDate');let url;try{url=new URL(link)}catch{return null}if(url.protocol!=='https:'||!(url.hostname==='stj.jus.br'||url.hostname.endsWith('.stj.jus.br')))return null;return{title,url:url.href,date:Number.isFinite(Date.parse(date))?new Date(date).toISOString():null}}).filter(x=>x&&x.title).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)).slice(0,3)}
let cached=null;async function newsResponse(){if(cached&&Date.now()-cached.time<900000)return Response.json(cached.data);try{const r=await fetch(FEED,{signal:AbortSignal.timeout(8000),headers:{Accept:'application/rss+xml, application/xml, text/xml'}});if(!r.ok)throw Error('upstream');const items=parseFeed(await r.text());if(!items.length)throw Error('empty');const data={items,updatedAt:new Date().toISOString()};cached={data,time:Date.now()};return Response.json(data,{headers:{'Cache-Control':'public, max-age=900'}})}catch{return Response.json({error:'Notícias indisponíveis'},{status:503})}}

