export default {async fetch(request){const url=new URL(request.url);if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method not allowed",{status:405});if(url.pathname==="/api/noticias")return newsResponse();let path=url.pathname;if(!path.split("/").at(-1).includes("."))path=(path.endsWith("/")?path:path+"/")+"index.html";const a=assets[path];if(!a)return new Response("Página não encontrada",{status:404});const bytes=Uint8Array.from(atob(a.base64),c=>c.charCodeAt(0));return new Response(request.method==="HEAD"?null:bytes,{headers:{"Content-Type":a.type,"X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","Cache-Control":a.type.startsWith("text/html")?"no-cache":"public,max-age=3600"}})}};